import { useState } from 'react';
import styled from 'styled-components';

import { useGuitarInput } from 'app/services/GuitarInputService/useGuitarInput';
import { useAudioOutput } from 'app/services/SynthesizerService/hooks/useAudioOutput';

import { InputSoundControls } from './InputSoundControls';
import { NoiseGateControls } from './NoiseGateControls';

export const EffectsRouting = ({
  guitar,
  live,
  onLiveChange,
  output,
  recording,
}: {
  guitar: ReturnType<typeof useGuitarInput>;
  live: boolean;
  onLiveChange: (value: boolean) => void;
  output: ReturnType<typeof useAudioOutput>;
  recording: boolean;
}) => {
  const [switching, setSwitching] = useState(false);
  const canSelectOutput = live ? guitar.canSelectOutput : output.supported;
  const outputDeviceId = live ? guitar.outputDeviceId : output.deviceId;
  const inputs = guitar.devices.filter(device => device.deviceId);
  const outputs = guitar.outputs.filter(
    device => device.deviceId && device.deviceId !== 'default',
  );

  return (
    <Routing aria-label="Маршрутизация звука">
      <Fields>
        <label>
          Вход
          <select
            aria-label="Источник входа эффектов"
            value={live ? `audio:${guitar.deviceId}` : 'instrument'}
            disabled={recording || guitar.connecting}
            onChange={event => {
              const value = event.target.value;
              guitar.stopMonitoring();
              onLiveChange(value !== 'instrument');
              if (value !== 'instrument') {
                const id = value.slice('audio:'.length);
                if (!guitar.connected || id !== guitar.deviceId)
                  guitar.selectDevice(id);
              }
            }}
          >
            <option value="instrument">Qwertophone · клавиатура / MIDI</option>
            {guitar.supported && (
              <>
                <option value="audio:">Системный аудиовход</option>
                {guitar.deviceId &&
                  !inputs.some(
                    device => device.deviceId === guitar.deviceId,
                  ) && (
                    <option value={`audio:${guitar.deviceId}`}>
                      Выбранный аудиовход
                    </option>
                  )}
                {inputs.map((device, index) => (
                  <option
                    key={device.deviceId}
                    value={`audio:${device.deviceId}`}
                  >
                    {device.label || `Аудиовход ${index + 1}`}
                  </option>
                ))}
              </>
            )}
          </select>
        </label>
        {live && guitar.connected && guitar.channels > 1 && (
          <label>
            Канал
            <select
              aria-label="Канал входа эффектов"
              value={guitar.channel}
              disabled={recording}
              onChange={event =>
                guitar.selectChannel(Number(event.target.value))
              }
            >
              {Array.from({ length: guitar.channels }, (_, channel) => (
                <option key={channel} value={channel}>
                  Вход {channel + 1}
                </option>
              ))}
            </select>
          </label>
        )}
        <label>
          Выход
          <select
            aria-label="Устройство выхода эффектов"
            value={outputDeviceId}
            disabled={
              !canSelectOutput ||
              (live && !guitar.connected) ||
              switching ||
              output.switching
            }
            onChange={async event => {
              const id = event.target.value;
              if (!live) {
                void output.selectDevice(id);
                return;
              }
              setSwitching(true);
              await guitar.selectOutput(id);
              setSwitching(false);
            }}
          >
            <option value="">Системный выход</option>
            {outputDeviceId &&
              !outputs.some(device => device.deviceId === outputDeviceId) && (
                <option value={outputDeviceId}>Выбранный аудиовыход</option>
              )}
            {outputs.map((device, index) => (
              <option key={device.deviceId} value={device.deviceId}>
                {device.label || `Аудиовыход ${index + 1}`}
              </option>
            ))}
          </select>
        </label>
        <button
          type="button"
          disabled={
            !guitar.supported ||
            guitar.requestingDevices ||
            guitar.connecting ||
            recording
          }
          title="Разрешите доступ к микрофону, чтобы увидеть все доступные входы и выходы. Звук не включается."
          onClick={guitar.requestDevices}
        >
          {guitar.requestingDevices
            ? 'Поиск устройств…'
            : 'Обновить устройства'}
        </button>
      </Fields>
      {!canSelectOutput && (
        <Hint>Аудиовыход выбирается в настройках системы или браузера.</Hint>
      )}
      {!guitar.supported && <Hint>Аудиовход недоступен в этом браузере.</Hint>}
      {live && (
        <LiveControls>
          {guitar.connecting ? (
            <button type="button" onClick={guitar.disconnect}>
              Отменить подключение
            </button>
          ) : guitar.connected ? (
            <>
              <button
                type="button"
                aria-pressed={guitar.monitoring}
                onClick={
                  guitar.monitoring
                    ? guitar.stopMonitoring
                    : guitar.startMonitoring
                }
              >
                {guitar.monitoring
                  ? 'Выключить живой звук'
                  : 'Включить живой звук'}
              </button>
              <button type="button" onClick={guitar.disconnect}>
                Отключить вход
              </button>
            </>
          ) : (
            <button
              type="button"
              disabled={recording}
              onClick={() => guitar.connect()}
            >
              Подключить аудиовход
            </button>
          )}
          <span role="status">
            {guitar.connecting
              ? guitar.connectionStatus
              : guitar.monitoring
              ? 'Живой звук включён'
              : 'Живой звук выключен'}
          </span>
          <Hint>
            Используйте наушники. Смена канала или выхода выключает живой звук.
            Компрессор добавляет задержку.
          </Hint>
        </LiveControls>
      )}
      {live && <InputSoundControls guitar={guitar} />}
      {live && guitar.inputSound !== 'instrument' && (
        <NoiseGateControls
          settings={guitar.noiseGate}
          onChange={guitar.updateNoiseGate}
        />
      )}
      {(guitar.error || (!live && output.error)) && (
        <Hint role="alert">{guitar.error || output.error}</Hint>
      )}
    </Routing>
  );
};

const Routing = styled.section`
  margin-bottom: 16px;
  padding: 12px;
  border: 1px solid ${p => p.theme.border};
  border-radius: 8px;
  background: ${p => p.theme.background};
  font-size: 12px;
  button,
  select {
    min-height: 36px;
    font: inherit;
  }
  select {
    width: 100%;
    min-width: 0;
  }
`;

const Fields = styled.div`
  display: flex;
  flex-wrap: wrap;
  align-items: end;
  gap: 12px;
  label {
    display: flex;
    flex: 1 1 200px;
    min-width: 0;
    flex-direction: column;
    gap: 6px;
    color: ${p => p.theme.textSecondary};
  }
  @media (max-width: 480px) {
    label {
      flex-basis: 100%;
    }
    button {
      width: 100%;
    }
  }
`;

const LiveControls = styled.div`
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  margin-top: 12px;
  [aria-pressed='true'] {
    color: ${p => p.theme.primary};
    border-color: currentColor;
  }
`;

const Hint = styled.p`
  flex-basis: 100%;
  margin: 8px 0 0;
  color: ${p => p.theme.textSecondary};
  line-height: 1.5;
  &[role='alert'] {
    color: ${p => p.theme.danger};
  }
`;
