import { keyboardButtons } from 'app/services/KeyboardService/mappings';
import { scaleApplicatures } from 'app/services/KeyboardService/scaleApplicatures';
import { KeyCode } from 'app/services/KeyboardService/types';
import { clampTempo } from 'app/services/MelodiesService/tempo';
import {
  getMetronomeRhythm,
  resolveMetronomeMeter,
} from 'app/services/MetronomeService/rhythm';
import { chromaticNotes } from 'app/services/NotesService/chromaticNotes';
import { JustNote, Octave } from 'app/services/NotesService/types';
import { timbresLinks } from 'app/services/SynthesizerService/timbres';
import { Timbre } from 'app/services/SynthesizerService/types';

import { readPreferences, writePreferences } from 'utils/preferences';

import { isMicrotonalScale, microtonalInstrument } from './microtonal';
import { Mode, Scale, getScale, scales } from './scales';
import { SettingsState } from './slice/types';

const validInteger = (
  value: unknown,
  min: number,
  max: number,
  fallback: number,
) =>
  typeof value === 'number' &&
  Number.isInteger(value) &&
  value >= min &&
  value <= max
    ? value
    : fallback;

export const loadSettings = (): SettingsState => {
  const saved = readPreferences('settings');
  const customScale =
    Array.isArray(saved.customScale) &&
    saved.customScale.length &&
    saved.customScale.every(note => chromaticNotes.includes(note))
      ? (Array.from(new Set(saved.customScale)) as JustNote[])
      : undefined;
  let scale: Scale =
    typeof saved.scale === 'string' &&
    Object.prototype.hasOwnProperty.call(scales, saved.scale) &&
    (saved.scale !== 'custom' || customScale)
      ? (saved.scale as Scale)
      : 'diatonic';
  const modes = scales[scale].modes as readonly Mode[];
  let mode = modes.includes(saved.mode as Mode)
    ? (saved.mode as Mode)
    : modes[0];
  const legacyTimbres = [
    'sine',
    'square',
    'triangle',
    'sawtooth',
    'custom',
    'celeste',
    'bass',
    'harpsichord',
    'horn',
  ];
  const savedTimbre =
    saved.timbre && typeof saved.timbre === 'object'
      ? (saved.timbre as Record<string, unknown>).title
      : saved.timbre;
  const timbre =
    typeof savedTimbre === 'string' &&
    (timbresLinks.some(item => item.title === savedTimbre) ||
      legacyTimbres.includes(savedTimbre))
      ? (savedTimbre as Timbre)
      : timbresLinks[0].title;
  if (
    isMicrotonalScale(scale) &&
    microtonalInstrument(timbre)?.scale !== scale
  ) {
    scale = microtonalInstrument(timbre)?.scale ?? 'diatonic';
    mode = scales[scale].modes[0];
  }
  const applicature =
    Array.isArray(saved.applicature) &&
    saved.applicature.length &&
    saved.applicature.every(key =>
      Object.prototype.hasOwnProperty.call(keyboardButtons, key),
    )
      ? (saved.applicature as KeyCode[])
      : scaleApplicatures[scale];
  return {
    octave: validInteger(saved.octave, 0, 8, 3) as Octave,
    pitch: validInteger(saved.pitch, -127, 127, 0),
    scale,
    mode,
    customScale,
    applicature,
    scaleNotes: getScale(scale, mode, customScale),
    timbre,
    bpm: clampTempo(
      typeof saved.bpm === 'number' && Number.isFinite(saved.bpm)
        ? saved.bpm
        : 90,
    ),
    timeSignature: resolveMetronomeMeter(
      saved.metronomeMeter,
      saved.timeSignature as SettingsState['timeSignature'],
    ),
    metronomeRhythm: getMetronomeRhythm(saved.metronomeRhythm),
    optimizeTablature: saved.optimizeTablature === true,
    optimizeFullTablature:
      saved.optimizeTablature === true && saved.optimizeFullTablature === true,
    melodyContext:
      typeof saved.melodyContext === 'string' ? saved.melodyContext : undefined,
    isRecording: false,
  };
};

export const saveSettings = (state: SettingsState) => {
  const { isRecording, scaleNotes, ...preferences } = state;
  writePreferences('settings', preferences);
};
