import { ReactNode, useId, useRef, useState } from 'react';
import styled from 'styled-components';

import { useHeaderPopupDismiss } from './HeaderPopup';
import { MelodyActionButton, MelodyActionIcon } from './MelodyAction';

type Icon =
  | 'back'
  | 'pause'
  | 'add'
  | 'delete'
  | 'undo'
  | 'redo'
  | 'snap'
  | 'zoom'
  | 'help'
  | 'info'
  | 'tempo'
  | 'edit'
  | 'export';

export const MelodyEditorIcon = ({ icon }: { icon: Icon }) => (
  <svg
    width="20"
    height="20"
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="1.8"
    strokeLinecap="round"
    strokeLinejoin="round"
    aria-hidden="true"
    focusable="false"
  >
    {icon === 'back' && <path d="m14 5-7 7 7 7M7 12h14" />}
    {icon === 'pause' && <path d="M8 5v14m8-14v14" strokeWidth="4" />}
    {icon === 'add' && <path d="M12 5v14M5 12h14" />}
    {icon === 'delete' && (
      <path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7" />
    )}
    {icon === 'undo' && <path d="m8 4-5 5 5 5M3 9h11a6 6 0 0 1 0 12" />}
    {icon === 'redo' && <path d="m16 4 5 5-5 5m5-5H10a6 6 0 0 0 0 12" />}
    {icon === 'snap' && (
      <path d="M5 3v9a7 7 0 0 0 14 0V3h-5v9a2 2 0 0 1-4 0V3ZM5 7h5m4 0h5" />
    )}
    {icon === 'zoom' && (
      <>
        <circle cx="10" cy="10" r="6" />
        <path d="m15 15 6 6M7 10h6m-3-3v6" />
      </>
    )}
    {(icon === 'help' || icon === 'info') && <circle cx="12" cy="12" r="9" />}
    {icon === 'help' && <path d="M9 9a3 3 0 0 1 6 0c0 2-3 2-3 5m0 3h.01" />}
    {icon === 'info' && <path d="M12 11v6m0-10h.01" />}
    {icon === 'tempo' && <path d="m12 3-7 17h14L12 3Zm0 12 7-8M8 20h8" />}
    {icon === 'edit' && (
      <path d="m15 4 5 5M4 20l5-1L20 8a3.5 3.5 0 0 0-5-5L4 14z" />
    )}
    {icon === 'export' && <path d="M12 3v13m-4-4 4 4 4-4M4 16v5h16v-5" />}
  </svg>
);

export const MelodyEditorPopover = ({
  label,
  icon,
  disabled = false,
  children,
}: {
  label: string;
  icon: Icon;
  disabled?: boolean;
  children: ReactNode;
}) => {
  const [open, setOpen] = useState(false);
  const trigger = useRef<HTMLButtonElement>(null);
  const popup = useRef<HTMLElement>(null);
  const id = useId();
  useHeaderPopupDismiss(open, setOpen, trigger, popup);
  const close = () => {
    setOpen(false);
    trigger.current?.focus();
  };
  return (
    <>
      <MelodyActionButton
        type="button"
        ref={trigger}
        aria-label={label}
        title={label}
        aria-expanded={open}
        aria-controls={open ? id : undefined}
        disabled={disabled}
        onClick={() => setOpen(!open)}
        onKeyDown={event => {
          if (event.key === 'Escape' && open) close();
        }}
      >
        <MelodyEditorIcon icon={icon} />
      </MelodyActionButton>
      {open && (
        <Panel
          ref={popup}
          id={id}
          aria-label={label}
          onKeyDown={event => {
            if (event.key === 'Escape') {
              event.preventDefault();
              close();
            }
          }}
        >
          <PanelHeader>
            <strong>{label}</strong>
            <MelodyActionButton
              type="button"
              aria-label={`Закрыть: ${label}`}
              title="Закрыть"
              onClick={close}
            >
              <MelodyActionIcon action="close" />
            </MelodyActionButton>
          </PanelHeader>
          {children}
        </Panel>
      )}
    </>
  );
};

const Panel = styled.aside`
  position: fixed;
  z-index: 40;
  top: calc(var(--app-header-height, 64px) + 64px);
  right: max(12px, calc((100vw - 1216px) / 2));
  width: min(440px, calc(100vw - 24px));
  max-height: calc(100vh - var(--app-header-height, 64px) - 88px);
  max-height: calc(100dvh - var(--app-header-height, 64px) - 88px);
  padding: 12px 16px 16px;
  box-sizing: border-box;
  overflow: auto;
  overscroll-behavior: contain;
  border: 1px solid ${p => p.theme.border};
  border-radius: 12px;
  background: ${p => p.theme.surface};
  color: ${p => p.theme.text};
  box-shadow: 0 8px 28px ${p => p.theme.shadow};
  font-size: 13px;
  p {
    color: ${p => p.theme.textSecondary};
  }
`;

const PanelHeader = styled.div`
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 8px;
`;
