import { ReactNode, createContext, useContext } from 'react';

import { useGuitarInput } from './useGuitarInput';

const GuitarInputContext = createContext<ReturnType<
  typeof useGuitarInput
> | null>(null);

export const GuitarInputProvider = ({ children }: { children: ReactNode }) => {
  const guitar = useGuitarInput();
  return (
    <GuitarInputContext.Provider value={guitar}>
      {children}
    </GuitarInputContext.Provider>
  );
};

export const useConnectedGuitarInput = () => {
  const guitar = useContext(GuitarInputContext);
  if (!guitar) throw new Error('GuitarInputProvider is required');
  return guitar;
};
