import { chromaticNotes } from 'app/services/NotesService/chromaticNotes';

import { getNoteDuration } from '../MelodiesService/timing';
import type { Melody, NoteExpression } from '../MelodiesService/types';
import { MelodyExportError } from './errors';

export interface ExportNote {
  pitch: number;
  start: number;
  end: number;
  expression?: NoteExpression;
}

// Merge overlapping voices of one pitch as the live player does. Adjacent
// notes keep separate attacks. All times remain in milliseconds.
export const getExportNotes = (melody: Melody): ExportNote[] => {
  if (!melody.notes.length)
    throw new MelodyExportError('В мелодии пока нет нот.');
  const notes = melody.notes.map(note => {
    const match = /^([A-G]#?)([0-8])$/.exec(note.note);
    const semitone = chromaticNotes.findIndex(name => name === match?.[1]);
    if (
      !match ||
      semitone < 0 ||
      !Number.isFinite(note.start) ||
      note.start < 0
    ) {
      throw new MelodyExportError(
        'В мелодии есть некорректные ноты или время начала.',
      );
    }
    return {
      pitch: (Number(match[2]) + 1) * 12 + semitone,
      start: note.start,
      end: note.start + getNoteDuration(note),
      ...(note.expression ? { expression: note.expression } : {}),
    };
  });
  notes.sort((a, b) => a.pitch - b.pitch || a.start - b.start);
  const merged: ExportNote[] = [];
  notes
    .filter(note => !note.expression)
    .forEach(note => {
      const previous = merged[merged.length - 1];
      if (previous?.pitch === note.pitch && note.start < previous.end) {
        previous.end = Math.max(previous.end, note.end);
      } else {
        merged.push({ ...note });
      }
    });
  return [...merged, ...notes.filter(note => note.expression)].sort(
    (a, b) => a.start - b.start || a.pitch - b.pitch,
  );
};
